#[test]
fn attract_map_projection_generation_follows_the_cpu_hdma_race() {
    let first_current = (0..ATTRACT_MAP_PROJECTION_WORDS)
        .find(|&line| attract_map_projection_current_word_is_visible(line));
    assert_eq!(first_current, Some(45));

    let mut ram = vec![0x55; 0x20000];
    let before_projection = vec![0xaa; ZeldaState::HDMA_DYNAMIC_TABLE_LEN];
    DisplayHdmaTableGeneration::AttractMapProjectionDuringScanout { before_projection }
        .compose_into(&mut ram);

    assert_eq!(
        &ram[HDMA_TABLE_DYNAMIC..HDMA_TABLE_DYNAMIC + 45 * 2],
        vec![0xaa; 45 * 2]
    );
    assert_eq!(
        &ram[HDMA_TABLE_DYNAMIC + 45 * 2..HDMA_TABLE_DYNAMIC + ATTRACT_MAP_PROJECTION_WORDS * 2],
        vec![0x55; (ATTRACT_MAP_PROJECTION_WORDS - 45) * 2]
    );
}

fn test_sync_all(state: &mut ZeldaState) {
    state.ram[0x42] = state.ram[0x42].wrapping_add(1);
}

fn test_run_frame_callback(state: &mut ZeldaState, input: u16, run_what: i32) {
    state.ram[0x43] = state.ram[0x43].wrapping_add(1);
    state.ram[0x44] = input as u8;
    state.ram[0x45] = run_what as u8;
}

fn test_run_frame_callback_calls_internal(state: &mut ZeldaState, input: u16, _: i32) {
    state.ram[0x43] = state.ram[0x43].wrapping_add(1);
    state.run_frame_internal(input, 0);
}

#[test]
fn desert_prayer_iris_checkpoint_preserves_primary_write_and_resumes_full_loop() {
    fn configure(state: &mut ZeldaState) {
        state.set_main_module(0x0e);
        state.set_submodule(5);
        state.set_subsubmodule(2);
        state.follower_link_state_mut().set_x(299);
        state.follower_link_state_mut().set_y(3472);
        state.set_bg2_h_copy2(173);
        state.set_bg2_v_copy2(3374);
    }

    let mut resumed = ZeldaState::new();
    configure(&mut resumed);
    resumed.CleanUpAndPrepDesertPrayerHDMA();
    resumed.set_spotlight_window_radius_byte(0x26);
    resumed.set_spotlight_window_state_byte(0);
    resumed.begin_desert_prayer_iris(
        crate::DesertPrayerIrisProgress::AfterPrimaryTableWrite {
            table_word: 87,
            y_buffer: 22,
        },
        DesertPrayerIrisCaller::InitializeCase2,
    );

    assert_eq!(
        resumed
            .game_state
            .display
            .spotlight_hdma
            .window_y_buffer_byte(),
        22,
    );
    assert_ne!(resumed.spotlight_hdma_table_dynamic_entry(87), 0);
    assert_eq!(resumed.spotlight_hdma_table_dynamic_entry(130), 0);

    resumed.complete_desert_prayer_iris(DesertPrayerIrisCaller::InitializeCase2);

    let mut uninterrupted = ZeldaState::new();
    configure(&mut uninterrupted);
    uninterrupted.DesertPrayer_InitializeIrisHDMA();
    for row in 0..240 {
        assert_eq!(
            resumed.spotlight_hdma_table_dynamic_entry(row),
            uninterrupted.spotlight_hdma_table_dynamic_entry(row),
            "Desert Prayer iris row {row} changed across continuation",
        );
    }
    assert_eq!(resumed.game_state.frame.subsubmodule, 3);
}

#[test]
fn desert_prayer_iris_before_primary_checkpoint_preserves_the_unpublished_word() {
    fn configure(state: &mut ZeldaState) {
        state.set_main_module(0x0e);
        state.set_submodule(5);
        state.set_subsubmodule(3);
        state.follower_link_state_mut().set_x(299);
        state.follower_link_state_mut().set_y(3472);
        state.set_bg2_h_copy2(173);
        state.set_bg2_v_copy2(3374);
        state.set_spotlight_window_radius_byte(0x26);
        state.set_spotlight_window_state_byte(0);
    }

    let mut resumed = ZeldaState::new();
    configure(&mut resumed);
    resumed.begin_desert_prayer_iris(
        crate::DesertPrayerIrisProgress::BeforePrimaryTableWrite {
            table_word: 222,
            y_buffer: 1,
        },
        DesertPrayerIrisCaller::PaletteFilterCase3,
    );
    assert_eq!(resumed.spotlight_hdma_table_dynamic_entry(222), 0);

    resumed.complete_desert_prayer_iris(DesertPrayerIrisCaller::PaletteFilterCase3);
    let mut uninterrupted = ZeldaState::new();
    configure(&mut uninterrupted);
    uninterrupted.DesertPrayer_BuildIrisHDMATable();
    for row in 0..240 {
        assert_eq!(
            resumed.spotlight_hdma_table_dynamic_entry(row),
            uninterrupted.spotlight_hdma_table_dynamic_entry(row),
            "Desert Prayer iris row {row} changed across a pre-primary continuation",
        );
    }
}

#[test]
fn palette_filter_prefix_and_remainder_equal_one_uninterrupted_source_call() {
    fn configure(state: &mut ZeldaState) {
        state.set_subsubmodule(3);
        state.set_countdown_word(0);
        state.set_mosaic_target_level(0);
        state.set_darkening_or_lightening_screen_word(2);
        for index in 0..256 {
            state.set_main_color(index, 0x4210);
            state.set_aux_color(index, 0x4210);
        }
    }

    let mut split = ZeldaState::new();
    configure(&mut split);
    split.apply_palette_filter_bounce_prefix(213);
    assert_ne!(
        split.game_state.display.palette_buffer.main_color(212),
        0x4210,
    );
    assert_eq!(
        split.game_state.display.palette_buffer.main_color(213),
        0x4210,
    );
    split.complete_apply_palette_filter_bounce_from(213);

    let mut whole = ZeldaState::new();
    configure(&mut whole);
    whole.ApplyPaletteFilter_bounce();

    for index in 0..256 {
        assert_eq!(
            split.game_state.display.palette_buffer.main_color(index),
            whole.game_state.display.palette_buffer.main_color(index),
            "palette color {index} changed across continuation",
        );
    }
    assert_eq!(split.game_state.frame.subsubmodule, 4);
    assert_eq!(
        split
            .game_state
            .display
            .palette_filter
            .darkening_or_lightening_screen_word(),
        whole
            .game_state
            .display
            .palette_filter
            .darkening_or_lightening_screen_word(),
    );
}

#[test]
fn authoritative_nmi_joypad_publication_overrides_newer_host_input() {
    let mut state = ZeldaState::new();
    state.original_timing_owner = OriginalTimingOwnerState::Live;
    state.original_timing_semantic_receipts = Some(OriginalTimingHostReceipts::new(
        7,
        0x0002,
        vec![OriginalTimingSemanticReceipt::JoypadPublication(
            JoypadPublication {
                high: 0,
                low: 0,
                high_filtered: 0,
                low_filtered: 0,
            },
        )],
    ));

    // Libretro has already supplied Right for this host call, but the NMI
    // completed before V228 auto-joy refreshed $4218. The atomic translated
    // handler initially sees the new host value; the timing authority then
    // publishes the exact Zelda bytes observed at the source handler return.
    state.interrupt_nmi_for_active_scanout(0x0002, None, false);
    assert_eq!(state.game_state.player.follower_link.joypad1h_last(), 0x40);
    state.apply_original_timing_joypad_publication();

    assert_eq!(state.game_state.player.follower_link.joypad1h_last(), 0);
    assert_eq!(state.game_state.player.follower_link.joypad1l_last(), 0);
    assert_eq!(state.game_state.player.follower_link.filtered_joypad_h(), 0);
    assert_eq!(state.game_state.player.follower_link.filtered_joypad_l(), 0);
    assert_eq!(state.game_state.player.follower_link.joypad1h_last2(), 0);
    assert_eq!(state.game_state.player.follower_link.joypad1l_last2(), 0);
    assert!(state
        .original_timing_semantic_receipts
        .as_ref()
        .unwrap()
        .semantic
        .is_empty());
}

#[test]
fn early_return_finishes_the_matching_authoritative_joypad_publication() {
    let mut state = ZeldaState::new();
    state.set_rom_startup_timing(true);
    state
        .install_original_timing_host_receipts(OriginalTimingHostReceipts::new(
            0,
            0x0002,
            vec![
                OriginalTimingSemanticReceipt::NmiAccepted(NmiUpdateGate::Open),
                OriginalTimingSemanticReceipt::NmiHandlerCompleted,
                OriginalTimingSemanticReceipt::JoypadPublication(JoypadPublication {
                    high: 0,
                    low: 0,
                    high_filtered: 0,
                    low_filtered: 0,
                }),
            ],
        ))
        .unwrap();
    let owns_dispatch = state.begin_original_timing_host_dispatch(0x0002);

    // The typed owner must drain the complete accepted-handler lifecycle.
    // Host close may carry a terminal acceptance, but it cannot synthesize a
    // handler or publish joypad bytes on behalf of an early-return branch.
    let phases = state.take_original_timing_nmi_phases();
    assert_eq!(
        phases,
        [
            OriginalTimingNmiPhase::Accepted(NmiUpdateGate::Open),
            OriginalTimingNmiPhase::HandlerCompleted,
        ],
    );
    let classification = classify_original_timing_nmi_phases_with_ownership(false, &phases);
    assert!(state
        .complete_original_timing_nmi_handler_for_active_scanout(
            classification.handler_completion,
            0x0002,
            None,
        )
        .completed());

    state.finish_original_timing_host_dispatch(owns_dispatch);

    let link = &state.game_state.player.follower_link;
    assert_eq!(link.joypad1h_last(), 0);
    assert_eq!(link.joypad1l_last(), 0);
    assert_eq!(link.filtered_joypad_h(), 0);
    assert_eq!(link.filtered_joypad_l(), 0);
    assert_eq!(link.joypad1h_last2(), 0);
    assert_eq!(link.joypad1l_last2(), 0);
    assert!(!state.original_timing_nmi_publication_pending);
    assert!(!state.original_timing_host_dispatch_active);
    assert!(state.original_timing_semantic_receipts.is_none());
}

fn test_run_frame_callback_observes_snes9x_semantic_receipts(
    state: &mut ZeldaState,
    input: u16,
    _: i32,
) {
    assert!(state.original_timing_host_dispatch_active);
    assert!(matches!(
        state.original_timing_owner,
        OriginalTimingOwnerState::Live
    ));
    let receipts = state
        .original_timing_semantic_receipts
        .as_ref()
        .expect("oracle semantic receipts remain visible during this host dispatch");
    assert_eq!(receipts.input_state, input);
    assert_eq!(
        receipts.semantic(),
        &[
            dungeon_reset_progress_receipt(
                sprite::DungeonResetSpritesCpuProgress::Load(
                    sprite::DungeonLoadSpritesCpuProgress {
                        normal_load_ordinal: 1,
                        slot: 1,
                        checkpoint: sprite::DungeonSpriteLoadCheckpoint::YHigh,
                    },
                ),
                OriginalTimingBoundary::NmiAccepted,
            ),
            OriginalTimingSemanticReceipt::NmiAccepted(NmiUpdateGate::Open),
        ]
    );
    assert!(state
        .take_original_timing_dungeon_reset_sprites_progress()
        .is_some());
    state.ram[0x43] = state.ram[0x43].wrapping_add(1);
}

